<?php
namespace Portal;
use PHPMailer\PHPMailer\PHPMailer;
final class Notifications {
 public static function quota(): void {$c=Core::config();if(!is_int($c['capacity_bytes'])||$c['capacity_bytes']<=0)return;$used=(int)Core::row('SELECT COALESCE(SUM(bytes),0) n FROM documents WHERE deleted_at IS NULL')['n'];$low=$c['capacity_bytes']-$used <= $c['alert_remaining_bytes'];$db=Core::db();$db->beginTransaction();try{$a=Core::row("SELECT active FROM alerts WHERE alert_key='storage' FOR UPDATE");if(!$a){Core::exec("INSERT INTO alerts(alert_key,active) VALUES('storage',0)");$a=['active'=>0];}if($low&&!(int)$a['active']){Core::exec("UPDATE alerts SET active=1,changed_at=UTC_TIMESTAMP() WHERE alert_key='storage'");Core::queue('storage',$c['admin_email'],'Spazio documenti sotto 2 GiB','Spazio disponibile: '.number_format(max(0,$c['capacity_bytes']-$used)/1073741824,2,',','.').' GiB. Controlla l’archivio file: '.$c['base_url'].'/?tab=archive','storage:'.gmdate('YmdHis').':'.bin2hex(random_bytes(4)));}elseif(!$low&&(int)$a['active'])Core::exec("UPDATE alerts SET active=0,changed_at=UTC_TIMESTAMP() WHERE alert_key='storage'");$db->commit();}catch(\Throwable $e){$db->rollBack();throw $e;}}
 public static function sendPending(int $limit=20): void {$c=Core::config();$limit=max(1,min(20,$limit));$jobs=Core::all('SELECT * FROM notification_queue WHERE sent_at IS NULL AND attempts<8 AND next_attempt_at<=UTC_TIMESTAMP() ORDER BY id LIMIT '.$limit);foreach($jobs as $job){try{$m=new PHPMailer(true);$m->isSMTP();$m->Host=$c['smtp_host'];$m->Port=(int)$c['smtp_port'];$m->SMTPAuth=true;$m->Username=$c['smtp_user'];$m->Password=$c['smtp_password'];$m->Timeout=5;$m->SMTPSecure=$m->Port===465?PHPMailer::ENCRYPTION_SMTPS:PHPMailer::ENCRYPTION_STARTTLS;$m->CharSet='UTF-8';$m->setFrom($c['mail_from'],'CA Automazione');$m->addAddress($job['recipient_email']);$m->Subject=$job['subject'];$m->Body=$job['body'];$m->send();Core::exec('UPDATE notification_queue SET sent_at=UTC_TIMESTAMP(),error=NULL WHERE id=?',[$job['id']]);}catch(\Throwable $e){Core::exec('UPDATE notification_queue SET attempts=attempts+1,error=?,next_attempt_at=DATE_ADD(UTC_TIMESTAMP(), INTERVAL 30 MINUTE) WHERE id=?',[mb_substr($e->getMessage(),0,1000),$job['id']]);}}}
}
